"""WKBRIDGE-295: Arx's side of the shared Q1 fixture (WisKey T02 / A04), regenerated by tests/test_wkbridge_295.py (drift = failure).

    py -3.12 smplwise_vms/backend/tests/wkbridge_fixture.py --write     # rewrite the JSON after a deliberate change

INPUT: WisKey's synthetic fixture `tests/fixtures/arx_station_pending_round2.json` (repository home-assistant-hikvision-intercom, commit
f842b2c523b22b8d1f4275ca9b02f78acb1010fd; the same blob 3e6488a21d0ceb5b66cd4056e23442b2bfa5ac47 at acc6509111ae2afbd2d54b620709960208d7e6c8),
copied below as data: person-a at revision 4, station-a disabled / current / applied 4, station-b disabled / pending / applied 3,
station-c only in WisKey's sync-operation queue (no assignment row). Synthetic ids only; no name, phone, PIN, card or address.

OUTPUT (same top-level shape as WisKey's file, plus an `arx` block):
  - `arx.access_state_v2`: the users/access_state_v2 answer Arx expects for that snapshot (Arx's reading of WisKey's projection; the
    projection itself is WisKey's - ASSUMED-PENDING-WISKEY-SHA until WisKey publishes the joint acceptance), parsed by Arx's ONE strict
    parser (services/wiskey_access_state.parse_result) so a self-contradicting answer cannot be recorded;
  - `arx.station_verdicts` / `arx.person_verdict`: Arx's real station-removal model on that answer (station_removal_verdict_v2,
    revocation_verdict_v2), mapped True -> "pending", False -> "proven_removed", None -> "unknown".

SEMANTICS: the per-station rule of pilot/WKB-295 @ 812b49a1df5f8b0ca31803754d114066ed56d6a1 (WisKey's global revocation_pending is not
consulted per station; a queued id with no assignment row cannot be attributed, so every other station stays UNKNOWN). For THIS input
main @ c37c75c917c79f694039c961174db37d57d43c4c gives the same verdicts (there the global flag already makes station-a UNKNOWN), so the
fixture does not move when WKB-295 merges. Where Arx and WisKey's text differ it is recorded, not resolved: WisKey writes "C without a
row stays UNKNOWN"; Arx answers station-c "pending" (an id in a removal queue is owed work) and station-a "unknown" (C cannot be placed)."""
from __future__ import annotations

import copy
import hashlib
import json
import sys
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
if str(HERE.parent) not in sys.path:
    sys.path.insert(0, str(HERE.parent))

from smplwise.services import wiskey_access_state as was  # noqa: E402

FIXTURE = HERE / "fixtures" / "arx_station_pending_round2_arx.json"

WISKEY_INPUT: dict[str, Any] = {
    "fixture_version": "wiskey-station-pending-round2.v1",
    "scope": "Synthetic projection input only; not native absence evidence or an Arx removal decision",
    "person_id": "person-a",
    "revision": 4,
    "snapshot": {
        "users": {
            "person-a": {
                "id": "person-a",
                "revision": 4,
                "access_timing_policy": None,
                "assignments": {
                    "station-a": {"enabled": False, "allowed_locks": [], "desired_revision": 4, "applied_revision": 4, "sync_state": "synced",
                                  "last_sync_at": "2026-10-23T00:00:00+00:00"},
                    "station-b": {"enabled": False, "allowed_locks": [], "desired_revision": 4, "applied_revision": 3, "sync_state": "pending",
                                  "last_sync_at": "2026-10-23T00:00:00+00:00"},
                },
            }
        },
        "bindings": {},
        "tombstones": {},
        "retired_cards": {},
        "retired_pins": {},
        "sync_operations": {"person-a/station-c": {"user_id": "person-a", "station_id": "station-c", "state": "pending", "verified_at": None}},
    },
    "expected_pending": {"bindings": [], "tombstones": [], "cards": [], "pins": [], "operations": ["station-b", "station-c"], "unverified": []},
}

PROVENANCE = {
    "producer": "SmplWise Arx",
    "branch": "pilot/WKBRIDGE-295",
    "base": "main c37c75c917c79f694039c961174db37d57d43c4c (v2.12.3)",
    "semantics": "pilot/WKB-295 812b49a1df5f8b0ca31803754d114066ed56d6a1 (per-station removal; a queued id without a row keeps other stations UNKNOWN)",
    "generator": "smplwise_vms/backend/tests/wkbridge_fixture.py",
    "wiskey_input": {
        "repository": "home-assistant-hikvision-intercom",
        "commit": "f842b2c523b22b8d1f4275ca9b02f78acb1010fd",
        "path": "tests/fixtures/arx_station_pending_round2.json",
        "git_blob": "3e6488a21d0ceb5b66cd4056e23442b2bfa5ac47",
        "file_sha256": "b82955330e3427639ca1a2f4c64a36c4a7aefa6736585dc98c531a67cad7048e",
    },
    "synthetic": True,
    "assumed": "ASSUMED-PENDING-WISKEY-SHA: the snapshot -> access_state_v2 projection is Arx's reading of WisKey's; WisKey owns it",
}

_VERDICT = {True: "pending", False: "proven_removed", None: "unknown"}


def canonical(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _project(inp: dict[str, Any]) -> dict[str, Any]:
    """The access_state_v2 answer for WisKey's synthetic snapshot (one present person, no policy, no groups, no PIN)."""
    pid, rev = inp["person_id"], inp["revision"]
    person = inp["snapshot"]["users"][pid]
    # owed work per station: a queued sync operation, or an assignment row that is behind the person's revision (WisKey's
    # expected_pending lists station-b, whose row is pending at applied 3, next to the queued station-c)
    ops = {o["station_id"] for o in inp["snapshot"]["sync_operations"].values() if o["user_id"] == pid and o["state"] == "pending"}
    rows = []
    for sid, a in sorted(person["assignments"].items()):
        current = a["desired_revision"] == rev and a["applied_revision"] == rev and a["sync_state"] == "synced"
        if not current:
            ops.add(sid)
        rows.append({"station_id": sid, "enabled": a["enabled"], "allowed_locks": list(a["allowed_locks"]), "desired_revision": a["desired_revision"],
                     "applied_revision": a["applied_revision"], "sync_state": a["sync_state"], "applied": True if current else False})
    pending = {"bindings": [], "tombstones": [], "cards": [], "pins": [], "operations": sorted(ops), "unverified": []}
    removal = any(pending[q] for q in was.REMOVAL_QUEUES)
    enabled = [r["applied"] for r in rows if r["enabled"]]
    synced = None if not enabled else False if False in enabled else None if None in enabled else True
    return {"schema_version": was.SCHEMA_V2, "observation": was.OBSERVATION, "scope": was.SCOPE, "user_id": pid, "person_revision": rev,
            "presence": "present", "revocation_pending": True if removal else (None if pending["unverified"] else False),
            "stations_synced": synced, "assignments": rows, "timing_policy": person["access_timing_policy"], "pending": pending,
            "central_revocation_predicate": was.CENTRAL_REVOCATION_PREDICATE,
            # a station block of a still-present person, not a whole-person revocation (the person keeps the record)
            "central_revoked": False}


def build() -> dict[str, Any]:
    inp = copy.deepcopy(WISKEY_INPUT)
    pid, rev = inp["person_id"], inp["revision"]
    answer = _project(inp)
    state = was.parse_result(copy.deepcopy(answer), user_id=pid, revision=rev, expect=was.SCHEMA_V2)  # strict: refuses a contradiction
    if {q: list(v) for q, v in state.pending.as_dict().items()} != inp["expected_pending"]:
        raise AssertionError("the projected queues differ from WisKey's expected_pending")
    stations = sorted(set(inp["snapshot"]["users"][pid]["assignments"]) | set(inp["expected_pending"]["operations"]))
    verdicts = {sid: _VERDICT[was.station_removal_verdict_v2(state, person_id=pid, revision=rev, station_id=sid)] for sid in stations}
    person = _VERDICT[was.revocation_verdict_v2(state, person_id=pid, revision=rev, last_known_stations=frozenset(stations))]
    return {
        "fixture_version": "arx-station-pending-round2.v1",
        "scope": "Synthetic; Arx's station-removal model on WisKey's synthetic round-2 input. Not native absence evidence, not a physical "
                 "removal at any door, not an Arx removal decision by itself",
        "person_id": pid,
        "revision": rev,
        "snapshot": inp["snapshot"],
        "expected_pending": inp["expected_pending"],
        "provenance": {**PROVENANCE, "wiskey_input_canonical_sha256": hashlib.sha256(canonical(WISKEY_INPUT).encode("utf-8")).hexdigest()},
        "arx": {
            "access_state_v2": answer,
            "station_verdicts": verdicts,
            "person_verdict": person,
            "notes": {
                "station-a": "disabled row applied at revision 4, but station-c is queued with no assignment row and cannot be attributed: UNKNOWN",
                "station-b": "named in operations (applied 3 < desired 4): removal work owed",
                "station-c": "named in operations with no assignment row: removal work owed; never proven removed from this answer",
                "person": "removal queues are not empty: the person is not clean (a station proof is never a person clean)",
            },
        },
    }


def render() -> str:
    return json.dumps(build(), indent=2, sort_keys=False, ensure_ascii=False) + "\n"


if __name__ == "__main__":
    if sys.argv[1:] == ["--write"]:
        FIXTURE.write_text(render(), encoding="utf-8", newline="\n")
        print(f"wrote {FIXTURE.name}")
    else:
        sys.stdout.write(render())
